/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["javascript"]={"Datentypen":"نوع‌های داده","Zahlen, Text und Boolean unterscheiden":"عدد، متن و Boolean را از هم جدا کنید","Zahlen ohne Anführungszeichen":"عددها بدون علامهٔ نقل‌قول","Eine Zahl wie 12 lässt sich direkt berechnen. Ohne Anführungszeichen speichert JavaScript einen numerischen Wert. Für einen festen Preis ist const geeignet. Ein Preisetikett trägt eine Zahl, nicht den geschriebenen Namen der Zahl.":"عددی مثل 12 را می‌شود مستقیم حساب کرد. بدون علامهٔ نقل‌قول، JavaScript یک مقدار عددی نگه می‌دارد. برای یک قیمت ثابت const مناسب است. یک برچسب قیمت یک عدد دارد، نه نام نوشته‌شدهٔ آن عدد را.","Zeile 1 legt preis mit `const` fest; Zeile 2 legt ort als Zeichenkette an. Vergleiche `12 + 3` mit `'12' + 3` und beobachte `15` gegenüber `123`.":"خط 1 ‏preis را با `const` تعیین می‌کند؛ خط 2 ‏ort را به شکل رشتهٔ متنی می‌سازد. `12 + 3` را با `'12' + 3` مقایسه کنید و `15` را در برابر `123` ببینید.","Strings als Textwerte":"String به عنوان مقدار متنی","Ein Ortsname wird als String gespeichert. Dafür schreibst du den Text zwischen Anführungszeichen. Mit einem Pluszeichen lassen sich zwei Strings verbinden. Eine Postkarte enthält Buchstaben und wird nicht wie ein Geldbetrag addiert. `const ort = 'Bonn';` bindet den Text Bonn an den Namen ort. `console.log(ort)` schreibt diesen Text in die Entwicklerkonsole. Setze statt Bonn deinen eigenen Wohnort ein und behalte die Anführungszeichen.":"نام یک جا به شکل String نگه داشته می‌شود. برای این کار متن را بین علامهٔ نقل‌قول می‌نویسید. با علامهٔ جمع می‌شود دو String را به هم وصل کرد. یک کارت پستال حروف دارد و مثل یک مبلغ پول جمع زده نمی‌شود. `const ort = 'Bonn';` متن Bonn را به نام ort وصل می‌کند. `console.log(ort)` این متن را در کنسول توسعه‌دهنده می‌نویسد. به جای Bonn نام شهر خودتان را بگذارید و علامهٔ نقل‌قول را نگه دارید.","`const ort = 'Bonn';` bindet den Text Bonn an den Namen ort. `console.log(ort)` schreibt diesen Text in die Entwicklerkonsole.":"`const ort = 'Bonn';` متن Bonn را به نام ort وصل می‌کند. `console.log(ort)` این متن را در کنسول توسعه‌دهنده می‌نویسد.","Boolean true und false":"Boolean ‏true و false","Ein Boolean ist entweder true oder false. Er steht ohne Anführungszeichen im Code. So kannst du Zustände wie offen oder geschlossen speichern. Ein Lichtschalter hat zwei Zustände; Boolean bildet genau diese Unterscheidung ab.":"یک Boolean یا true است یا false. بدون علامهٔ نقل‌قول در کد نوشته می‌شود. به این ترتیب می‌توانید وضعیت‌هایی مثل باز یا بسته را نگه دارید. یک سویچ چراغ دو وضعیت دارد؛ Boolean دقیقاً همین تفاوت را نشان می‌دهد.","`const offen = true;` legt einen echten Wahrheitswert an. `if (offen)` kann damit eine Entscheidung treffen, ohne Text zu vergleichen.":"`const offen = true;` یک مقدار درست/نادرست واقعی می‌سازد. `if (offen)` با آن می‌تواند تصمیم بگیرد، بدون اینکه متن را مقایسه کند.","Mit typeof kontrollieren":"بررسی با typeof","typeof zeigt den Typ eines Werts an. typeof 12 liefert number, typeof '12' liefert string. Teste den Unterschied in der Konsole. Ein Etikett am Vorratsglas sagt dir, was darin liegt; `typeof` übernimmt diese Aufgabe für Werte. `console.log(typeof 12);` zeigt `number` als Typ an. `console.log(typeof '12');` zeigt `string`, obwohl die Zeichen gleich aussehen. Notiere beide Ergebnisse, bevor du weitere Werte ausprobierst.":"typeof نوع یک مقدار را نشان می‌دهد. typeof 12 نتیجهٔ number و typeof '12' نتیجهٔ string می‌دهد. این تفاوت را در کنسول آزمایش کنید. برچسب روی یک شیشهٔ ذخیره به شما می‌گوید داخلش چیست؛ `typeof` همین کار را برای مقدارها می‌کند. `console.log(typeof 12);` ‏`number` را به عنوان نوع نشان می‌دهد. `console.log(typeof '12');` ‏`string` را نشان می‌دهد، با اینکه حروف یکسان به نظر می‌رسند. هر دو نتیجه را یادداشت کنید، پیش از اینکه مقدارهای دیگر را امتحان کنید.","`console.log(typeof 12);` zeigt `number` als Typ an. `console.log(typeof '12');` zeigt `string`, obwohl die Zeichen gleich aussehen.":"`console.log(typeof 12);` ‏`number` را به عنوان نوع نشان می‌دهد. `console.log(typeof '12');` ‏`string` را نشان می‌دهد، با اینکه حروف یکسان به نظر می‌رسند.","Zahl als Text gespeichert":"عدد به شکل متن نگه داشته شد","Falsch: `const preis = '12'; console.log(preis + 3);` ergibt `123` statt `15` in der Konsole. Der Preis ist ein String und das Pluszeichen hängt Text an. Richtig: `const preis = 12; console.log(preis + 3);` zeigt `15`.":"اشتباه: `const preis = '12'; console.log(preis + 3);` در کنسول به جای `15` نتیجهٔ `123` می‌دهد. قیمت یک String است و علامهٔ جمع متن را می‌چسپاند. درست: `const preis = 12; console.log(preis + 3);` ‏`15` را نشان می‌دهد.","Boolean fälschlich in Anführungszeichen":"Boolean به اشتباه در علامهٔ نقل‌قول","Falsch: `const offen = 'false'; if (offen) console.log('offen');` zeigt trotzdem `offen`, weil der nichtleere String als wahr gilt. Richtig: `const offen = false; if (offen) console.log('offen');` zeigt keine Meldung.":"اشتباه: `const offen = 'false'; if (offen) console.log('offen');` با این حال `offen` را نشان می‌دهد، چون یک String غیرخالی درست حساب می‌شود. درست: `const offen = false; if (offen) console.log('offen');` هیچ پیامی نشان نمی‌دهد.","Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.":"مثال را در ویرایشگر به کار ببرید و پیش‌نمایش یا کنسول را بررسی کنید.","Vergleiche die Schreibweise mit dem Codebeispiel.":"املا را با مثال کد مقایسه کنید.","Passende HTML-Struktur vorhanden.":"ساختار مناسب HTML وجود دارد.","JavaScript enthält die geübte Technik.":"JavaScript تکنیک تمرین‌شده را دارد.","Was ist typeof 12?":"typeof 12 چیست؟","Hier passt „number“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „number“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Diese Antwort beschreibt nicht die gesuchte Funktion.":"این جواب کار خواسته‌شده را توصیف نمی‌کند.","Diese Antwort beschreibt die gesuchte Funktion.":"این جواب کار خواسته‌شده را توصیف می‌کند.","Was ist typeof '12'?":"typeof '12' چیست؟","Hier passt „string“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „string“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Welcher Wert ist ein Boolean?":"کدام مقدار یک Boolean است؟","Hier passt „true“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „true“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Datentypen ist die genaue JavaScript-Schreibweise wichtig.":"در نوع‌های داده، املای دقیق JavaScript مهم است.","Nutze die Lösung `const preis = 12; const ort = 'Bonn'; const offen = true;` als Vergleich für deine eigene Übung.":"از راه‌حل `const preis = 12; const ort = 'Bonn'; const offen = true;` برای مقایسه با تمرین خودتان استفاده کنید.","Arrays":"آرایه‌ها","Mehrere Einträge in einer Liste speichern":"چند عنصر را در یک لست نگه دارید","Eine Einkaufsliste anlegen":"ساختن یک لست خرید","Ein Array sammelt mehrere Werte in eckigen Klammern. Trenne die Einträge mit Kommas. So bleibt eine Einkaufsliste in einer einzigen Variablen. Eine Einkaufstasche enthält mehrere Produkte; ein Array hält ihre Namen zusammen.":"یک آرایه چند مقدار را داخل قوس‌های چهارگوش جمع می‌کند. عنصرها را با کامه جدا کنید. به این ترتیب یک لست خرید در یک متغیر واحد می‌ماند. یک خریطهٔ خرید چند جنس دارد؛ یک آرایه نام‌های آن‌ها را یک‌جا نگه می‌دارد.","`const einkauf = ['Brot', 'Milch'];` erzeugt zwei Einträge. Die eckigen Klammern gehören zur Liste, die Anführungszeichen zu jedem Text.":"`const einkauf = ['Brot', 'Milch'];` دو عنصر می‌سازد. قوس‌های چهارگوش به لست تعلق دارند و علامهٔ نقل‌قول به هر متن.","Einträge mit Index lesen":"خواندن عنصرها با شاخص","Die erste Position eines Arrays hat den Index null. einkauf[0] liefert daher Brot. Der zweite Eintrag wird über einkauf[1] gelesen. Regalfächer haben Nummern; JavaScript beginnt die Nummerierung bei null. `console.log(einkauf[0]);` liest Brot aus dem ersten Fach. `console.log(einkauf[1]);` liest Milch aus dem zweiten Fach. Ein Zugriff auf `einkauf[9]` liefert dagegen `undefined`.":"اولین جایگاه یک آرایه شاخص صفر دارد. به همین دلیل einkauf[0] ‏Brot را می‌دهد. عنصر دوم با einkauf[1] خوانده می‌شود. خانه‌های الماری شماره دارند؛ JavaScript شمارش را از صفر شروع می‌کند. `console.log(einkauf[0]);` ‏Brot را از خانهٔ اول می‌خواند. `console.log(einkauf[1]);` ‏Milch را از خانهٔ دوم می‌خواند. اما دسترسی به `einkauf[9]` نتیجهٔ `undefined` می‌دهد.","`console.log(einkauf[0]);` liest Brot aus dem ersten Fach. `console.log(einkauf[1]);` liest Milch aus dem zweiten Fach.":"`console.log(einkauf[0]);` ‏Brot را از خانهٔ اول می‌خواند. `console.log(einkauf[1]);` ‏Milch را از خانهٔ دوم می‌خواند.","Mit push erweitern":"گسترش با push","Mit push fügst du einen neuen Eintrag am Ende hinzu. Die vorhandenen Werte bleiben erhalten. Probiere einkauf.push('Reis') in deinem Beispiel aus. Beim Einkaufen legst du neue Waren hinten in die Tasche; so arbeitet push. `einkauf.push('Reis');` ergänzt den String Reis. `console.log(einkauf);` zeigt danach alle drei Namen. Die Methode braucht runde Klammern und den gewünschten Wert.":"با push یک عنصر تازه را به آخر اضافه می‌کنید. مقدارهای موجود باقی می‌مانند. einkauf.push('Reis') را در مثال خود امتحان کنید. هنگام خرید جنس‌های تازه را در آخر خریطه می‌گذارید؛ push همین‌طور کار می‌کند. `einkauf.push('Reis');` ‏String ‏Reis را اضافه می‌کند. `console.log(einkauf);` بعد از آن هر سه نام را نشان می‌دهد. این متود به قوس‌های گرد و مقدار دلخواه نیاز دارد.","`einkauf.push('Reis');` ergänzt den String Reis. `console.log(einkauf);` zeigt danach alle drei Namen.":"`einkauf.push('Reis');` ‏String ‏Reis را اضافه می‌کند. `console.log(einkauf);` بعد از آن هر سه نام را نشان می‌دهد.","Die Länge abfragen":"پرسیدن طول","length gibt die Anzahl der Einträge zurück. Nach dem Hinzufügen sind es drei. Verwende die Eigenschaft ohne Klammern. Ein Kassenbon zählt Positionen, nicht den letzten Regalindex. `console.log(einkauf.length);` liefert nach push den Wert drei. Die Eigenschaft length wird ohne `()` geschrieben. Lösche testweise einen Eintrag und vergleiche die neue Anzahl.":"length تعداد عنصرها را می‌دهد. بعد از اضافه کردن، سه عنصر است. این ویژگی را بدون قوس به کار ببرید. یک رسید خرید ردیف‌ها را می‌شمارد، نه آخرین شاخص الماری را. `console.log(einkauf.length);` بعد از push مقدار سه را می‌دهد. ویژگی length بدون `()` نوشته می‌شود. به‌طور آزمایشی یک عنصر را پاک کنید و تعداد تازه را مقایسه کنید.","`console.log(einkauf.length);` liefert nach push den Wert drei. Die Eigenschaft length wird ohne `()` geschrieben.":"`console.log(einkauf.length);` بعد از push مقدار سه را می‌دهد. ویژگی length بدون `()` نوشته می‌شود.","Ersten Eintrag mit Index eins gesucht":"عنصر اول با شاخص یک جستجو شد","Falsch: `console.log(einkauf[1]);` zeigt `Milch`, obwohl du `Brot` erwartest. Arrays zählen ab null. Richtig: `console.log(einkauf[0]);` zeigt `Brot`.":"اشتباه: `console.log(einkauf[1]);` ‏`Milch` را نشان می‌دهد، با اینکه شما `Brot` را انتظار دارید. آرایه‌ها از صفر می‌شمارند. درست: `console.log(einkauf[0]);` ‏`Brot` را نشان می‌دهد.","push ohne Argument verwendet":"push بدون مقدار به کار رفت","Falsch: `einkauf.push();` fügt einen Eintrag mit dem Wert `undefined` hinzu; die Liste enthält danach keinen neuen Artikelnamen. Richtig: `einkauf.push('Reis');` ergänzt einen sichtbaren Einkauf.":"اشتباه: `einkauf.push();` یک عنصر با مقدار `undefined` اضافه می‌کند؛ لست بعد از آن هیچ نام جنس تازه‌ای ندارد. درست: `einkauf.push('Reis');` یک خرید قابل دید اضافه می‌کند.","Welcher Index ist der erste?":"کدام شاخص اولین است؟","Hier passt „0“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „0“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Wie wird Reis angehängt?":"Reis چطور اضافه می‌شود؟","Hier passt „einkauf.push('Reis')“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „einkauf.push('Reis')“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was liefert length?":"length چه می‌دهد؟","Anzahl der Einträge":"تعداد عنصرها","Ersten Text":"اولین متن","Letzten Namen":"آخرین نام","Hier passt „Anzahl der Einträge“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „تعداد عنصرها“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Arrays ist die genaue JavaScript-Schreibweise wichtig.":"در آرایه‌ها، املای دقیق JavaScript مهم است.","Nutze die Lösung `const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);` als Vergleich für deine eigene Übung.":"از راه‌حل `const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);` برای مقایسه با تمرین خودتان استفاده کنید.","Schleifen":"حلقه‌ها","Wiederholungen mit for und for...of schreiben":"تکرارها را با for و for...of بنویسید","Wiederholung verstehen":"فهمیدن تکرار","Eine Schleife führt denselben Ablauf mehrmals aus. Du musst die Anweisung nicht kopieren. Das ist bei einer Liste von Namen besonders praktisch. Eine Lehrkraft ruft alle Namen der Anwesenheitsliste nacheinander auf.":"یک حلقه یک روند را چند بار اجرا می‌کند. لازم نیست دستور را کاپی کنید. این برای یک لست نام‌ها به‌خصوص کاربردی است. یک معلم همهٔ نام‌های لست حاضری را یکی پس از دیگری صدا می‌زند.","`for (const name of namen)` besucht jeden vorhandenen Eintrag. Der Block in geschweiften Klammern wird für jeden Namen wiederholt.":"`for (const name of namen)` به هر عنصر موجود سر می‌زند. بلاک داخل قوس‌های گُل‌دار برای هر نام تکرار می‌شود.","for...of für Arrays":"for...of برای آرایه‌ها","for...of liest die Einträge nacheinander. Der Name im Schleifenkopf steht jeweils für den aktuellen Eintrag. Innerhalb der Klammern kannst du ihn ausgeben. Wie bei einer Runde durch mehrere Zimmer wird derselbe Arbeitsschritt wiederholt. `console.log(name);` verwendet im Block den jeweils aktuellen Namen. Nach dem letzten Eintrag endet for...of automatisch. Prüfe die Ausgabe mit einer Liste aus drei Personen.":"for...of عنصرها را یکی پس از دیگری می‌خواند. نام در سر حلقه هر بار به معنای عنصر فعلی است. داخل قوس‌ها می‌توانید آن را نشان دهید. مثل یک دور در چند اتاق، یک کار تکرار می‌شود. `console.log(name);` در بلاک هر بار نام فعلی را به کار می‌برد. بعد از آخرین عنصر، for...of خودکار تمام می‌شود. خروجی را با یک لست سه نفره بررسی کنید.","`console.log(name);` verwendet im Block den jeweils aktuellen Namen. Nach dem letzten Eintrag endet for...of automatisch.":"`console.log(name);` در بلاک هر بار نام فعلی را به کار می‌برد. بعد از آخرین عنصر، for...of خودکار تمام می‌شود.","Zähler mit let verwenden":"استفاده از شمارنده با let","Eine klassische for-Schleife benutzt oft let i = 0. Nach jedem Durchlauf erhöht i++ den Zähler. Mit i < 3 läuft der Block genau dreimal. Eine Nummernausgabe am Schalter zählt 0, 1, 2 und stoppt dann.":"یک حلقهٔ for کلاسیک اغلب let i = 0 را به کار می‌برد. بعد از هر دور i++ شمارنده را زیاد می‌کند. با i < 3 بلاک دقیقاً سه بار اجرا می‌شود. یک دستگاه نوبت در کاونتر 0، 1، 2 می‌شمارد و بعد می‌ایستد.","`let i = 0` setzt den Anfangswert, `i < 3` prüft die Grenze. `i++` erhöht die Nummer nach jedem Durchlauf um eins.":"`let i = 0` مقدار شروع را می‌گذارد و `i < 3` حد را بررسی می‌کند. `i++` بعد از هر دور شماره را یکی زیاد می‌کند.","Abbruchbedingung prüfen":"بررسی شرط توقف","Eine Schleife braucht eine erreichbare Abbruchbedingung. Ohne Änderung des Zählers kann sie endlos laufen. Prüfe den Ablauf zunächst mit wenigen Werten. Eine Rolltreppe ohne Ausgang wäre gefährlich; eine Schleife ohne Ende blockiert den Ablauf.":"یک حلقه به یک شرط توقف قابل رسیدن نیاز دارد. بدون تغییر شمارنده ممکن است بی‌پایان اجرا شود. روند را اول با چند مقدار کم بررسی کنید. یک زینهٔ برقی بدون خروجی خطرناک می‌بود؛ یک حلقهٔ بی‌پایان روند را متوقف می‌کند.","Bei `for (let i = 0; i < 3; i++)` ist das Ende erreichbar. Wenn `i++` fehlt, bleibt die Bedingung dauerhaft wahr.":"در `for (let i = 0; i < 3; i++)` پایان قابل رسیدن است. اگر `i++` نباشد، شرط همیشه درست می‌ماند.","Zähler wird nicht erhöht":"شمارنده زیاد نمی‌شود","Falsch: `for (let i = 0; i < 3;) console.log(i);` bleibt bei null und kann den Browser blockieren. Der Zähler ändert sich nie. Richtig: `for (let i = 0; i < 3; i++) console.log(i);` gibt `0`, `1`, `2` aus.":"اشتباه: `for (let i = 0; i < 3;) console.log(i);` در صفر می‌ماند و ممکن است براوزر را متوقف کند. شمارنده هرگز تغییر نمی‌کند. درست: `for (let i = 0; i < 3; i++) console.log(i);` ‏`0`، `1`، `2` را نشان می‌دهد.","Index läuft über das Arrayende":"شاخص از آخر آرایه می‌گذرد","Falsch: `for (let i = 0; i <= namen.length; i++) console.log(namen[i]);` gibt am Ende `undefined` aus. Der letzte gültige Index ist kleiner als length. Richtig: `for (let i = 0; i < namen.length; i++) console.log(namen[i]);`.":"اشتباه: `for (let i = 0; i <= namen.length; i++) console.log(namen[i]);` در آخر `undefined` نشان می‌دهد. آخرین شاخص معتبر از length کوچک‌تر است. درست: `for (let i = 0; i < namen.length; i++) console.log(namen[i]);`.","Was macht for...of?":"for...of چه کار می‌کند؟","Löscht Elemente":"عنصرها را پاک می‌کند","Liest Einträge nacheinander":"عنصرها را یکی پس از دیگری می‌خواند","Öffnet eine Webseite":"یک ویب‌سایت را باز می‌کند","Hier passt „Liest Einträge nacheinander“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „عنصرها را یکی پس از دیگری می‌خواند“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Wie viele Durchläufe hat i < 3 ab null?":"i < 3 از صفر چند دور دارد؟","Drei":"سه","Vier":"چهار","Zwei":"دو","Hier passt „Drei“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „سه“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was vermeidet eine Endlosschleife?":"چه چیزی از حلقهٔ بی‌پایان جلوگیری می‌کند؟","Längere Namen":"نام‌های طولانی‌تر","Mehr Farben":"رنگ‌های بیشتر","Erreichbare Abbruchbedingung":"شرط توقف قابل رسیدن","Hier passt „Erreichbare Abbruchbedingung“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „شرط توقف قابل رسیدن“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Schleifen ist die genaue JavaScript-Schreibweise wichtig.":"در حلقه‌ها، املای دقیق JavaScript مهم است.","Nutze die Lösung `const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }` als Vergleich für deine eigene Übung.":"از راه‌حل `const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }` برای مقایسه با تمرین خودتان استفاده کنید.","Funktionen":"تابع‌ها","Eigene Funktionen mit Parametern und return nutzen":"تابع‌های خودتان را با پارامتر و return به کار ببرید","Funktion benennen":"نام دادن به تابع","Eine Funktion bündelt einen wiederkehrenden Ablauf. function leitet die Definition ein. Der Name beschreibt die Aufgabe möglichst genau. Eine Kaffeemaschine erledigt nach dem Start immer dieselben Schritte.":"یک تابع یک روند تکراری را یک‌جا جمع می‌کند. function تعریف را شروع می‌کند. نام باید کار را تا حد ممکن دقیق توصیف کند. یک ماشین قهوه بعد از روشن شدن همیشه همان قدم‌ها را انجام می‌دهد.","`function doppelt(zahl)` gibt dem Ablauf einen Namen und einen Parameter. Die geschweiften Klammern umschließen die Rechenanweisung.":"`function doppelt(zahl)` به روند یک نام و یک پارامتر می‌دهد. قوس‌های گُل‌دار دستور حساب را در بر می‌گیرند.","Parameter entgegennehmen":"گرفتن پارامترها","In runden Klammern stehen Parameter. Beim Aufruf wird für jeden Parameter ein Wert übergeben. Im Funktionskörper kannst du damit rechnen. Eine Bestellung nennt die gewünschte Menge; ein Parameter übernimmt diesen Wert.":"داخل قوس‌های گرد پارامترها هستند. هنگام صدا زدن برای هر پارامتر یک مقدار داده می‌شود. در بدنهٔ تابع می‌توانید با آن حساب کنید. یک سفارش مقدار دلخواه را نام می‌برد؛ یک پارامتر این مقدار را می‌گیرد.","`doppelt(4)` übergibt die Zahl vier an den Parameter zahl. Im Funktionskörper steht dann für zahl genau dieser Wert.":"`doppelt(4)` عدد چهار را به پارامتر zahl می‌دهد. در بدنهٔ تابع به جای zahl دقیقاً همین مقدار قرار می‌گیرد.","Ergebnis zurückgeben":"پس دادن نتیجه","return liefert ein Ergebnis an den Aufrufer. Eine reine Konsolenausgabe gibt dagegen nicht automatisch einen Wert zurück. Nutze return für weitere Berechnungen. Ein Automat gibt nach dem Einwurf etwas zurück; return ist diese Rückgabe. `return zahl * 2;` berechnet und liefert das Ergebnis. `console.log` kann es anschließend sichtbar machen, ersetzt return aber nicht. Ohne return erhält der Aufrufer den Wert `undefined`.":"return یک نتیجه را به صدازننده می‌دهد. اما یک خروجی کنسول به تنهایی خودکار مقداری پس نمی‌دهد. return را برای حساب‌های بعدی به کار ببرید. یک ماشین فروش بعد از انداختن سکه چیزی پس می‌دهد؛ return همین پس دادن است. `return zahl * 2;` نتیجه را حساب می‌کند و می‌دهد. `console.log` بعد از آن می‌تواند آن را نشان دهد، اما جای return را نمی‌گیرد. بدون return صدازننده مقدار `undefined` را می‌گیرد.","`return zahl * 2;` berechnet und liefert das Ergebnis. `console.log` kann es anschließend sichtbar machen, ersetzt return aber nicht.":"`return zahl * 2;` نتیجه را حساب می‌کند و می‌دهد. `console.log` بعد از آن می‌تواند آن را نشان دهد، اما جای return را نمی‌گیرد.","Funktion aufrufen":"صدا زدن تابع","Die Definition allein führt den Code noch nicht aus. Erst doppelt(4) startet den Ablauf. Das Ergebnis dieser Rechnung ist acht. Ein beschrifteter Werkzeugkasten lässt dich ein Werkzeug schnell wiederfinden. Der Name doppelt beschreibt die Rechnung besser als ein beliebiger Buchstabe. `console.log(doppelt(4));` startet den Aufruf und zeigt acht. Verwende denselben Funktionsnamen beim Definieren und Aufrufen.":"تعریف به تنهایی کد را اجرا نمی‌کند. فقط doppelt(4) روند را شروع می‌کند. نتیجهٔ این حساب هشت است. یک جعبهٔ ابزار برچسب‌دار به شما کمک می‌کند یک ابزار را زود پیدا کنید. نام doppelt حساب را بهتر از یک حرف دلخواه توصیف می‌کند. `console.log(doppelt(4));` صدا زدن را شروع می‌کند و هشت را نشان می‌دهد. هنگام تعریف و صدا زدن یک نام تابع را به کار ببرید.","Der Name doppelt beschreibt die Rechnung besser als ein beliebiger Buchstabe. `console.log(doppelt(4));` startet den Aufruf und zeigt acht.":"نام doppelt حساب را بهتر از یک حرف دلخواه توصیف می‌کند. `console.log(doppelt(4));` صدا زدن را شروع می‌کند و هشت را نشان می‌دهد.","Funktion nicht aufgerufen":"تابع صدا زده نشد","Falsch: `function doppelt(x) { return x * 2; }` allein erzeugt keine Ausgabe; die Funktion wurde noch nicht gestartet. Richtig: `console.log(doppelt(4));` ruft sie auf und zeigt `8`.":"اشتباه: `function doppelt(x) { return x * 2; }` به تنهایی خروجی ندارد؛ تابع هنوز شروع نشده است. درست: `console.log(doppelt(4));` آن را صدا می‌زند و `8` را نشان می‌دهد.","console.log mit return verwechselt":"اشتباه گرفتن console.log با return","Falsch: `function doppelt(x) { console.log(x * 2); } console.log(doppelt(4));` zeigt zuerst `8`, dann `undefined`. console.log zeigt nur etwas an, gibt aber keinen Rückgabewert zurück. Richtig: `function doppelt(x) { return x * 2; } console.log(doppelt(4));` zeigt nur `8`.":"اشتباه: `function doppelt(x) { console.log(x * 2); } console.log(doppelt(4));` اول `8` و بعد `undefined` را نشان می‌دهد. console.log فقط چیزی را نشان می‌دهد، اما مقدار بازگشتی نمی‌دهد. درست: `function doppelt(x) { return x * 2; } console.log(doppelt(4));` فقط `8` را نشان می‌دهد.","Wozu dient ein Parameter?":"پارامتر برای چیست؟","Zum Löschen":"برای پاک کردن","Für Eingabewerte":"برای مقدارهای ورودی","Für CSS":"برای CSS","Hier passt „Für Eingabewerte“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „برای مقدارهای ورودی“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was macht return?":"return چه کار می‌کند؟","Gibt ein Ergebnis zurück":"یک نتیجه پس می‌دهد","Startet HTML":"HTML را شروع می‌کند","Öffnet eine Datei":"یک فایل را باز می‌کند","Hier passt „Gibt ein Ergebnis zurück“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „یک نتیجه پس می‌دهد“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Wann läuft die Funktion?":"تابع چه وقت اجرا می‌شود؟","Beim Speichern":"هنگام ذخیره","Beim Benennen":"هنگام نام دادن","Beim Aufruf":"هنگام صدا زدن","Hier passt „Beim Aufruf“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „هنگام صدا زدن“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Funktionen ist die genaue JavaScript-Schreibweise wichtig.":"در تابع‌ها، املای دقیق JavaScript مهم است.","Nutze die Lösung `function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));` als Vergleich für deine eigene Übung.":"از راه‌حل `function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));` برای مقایسه با تمرین خودتان استفاده کنید.","Objekte":"آبجکت‌ها","Zusammengehörige Eigenschaften verwalten":"ویژگی‌های مربوط به هم را مدیریت کنید","Personendaten bündeln":"جمع کردن معلومات یک شخص","Ein Objekt speichert zusammengehörige Angaben. Zwischen geschweiften Klammern stehen Eigenschaft und Wert. Ein Doppelpunkt trennt beide Teile. Eine Kontaktkarte hält Name und Ort einer Person beisammen.":"یک آبجکت معلومات مربوط به هم را نگه می‌دارد. بین قوس‌های گُل‌دار ویژگی و مقدار می‌آیند. یک دونقطه هر دو بخش را جدا می‌کند. یک کارت تماس نام و شهر یک شخص را کنار هم نگه می‌دارد.","`const person = { name: 'Amina', ort: 'Bonn' };` erstellt zwei Eigenschaften. Der Doppelpunkt verbindet jeweils Schlüssel und Wert.":"`const person = { name: 'Amina', ort: 'Bonn' };` دو ویژگی می‌سازد. دونقطه هر بار کلید و مقدار را به هم وصل می‌کند.","Eigenschaften mit Punkt lesen":"خواندن ویژگی‌ها با نقطه","Mit person.name liest du eine Eigenschaft. Du brauchst dafür keine zusätzliche Variable. Der Punkt verbindet den Objektnamen mit dem Eigenschaftsnamen. Auf einer Karte suchst du die Zeile Name, nicht die ganze Karte. `person.name` liest nur den gespeicherten Namen. `console.log(person.name);` zeigt ihn in der Konsole. Schreibst du versehentlich Name groß, erhältst du möglicherweise undefined.":"با person.name یک ویژگی را می‌خوانید. برای این کار به متغیر اضافی نیاز ندارید. نقطه نام آبجکت را با نام ویژگی وصل می‌کند. روی یک کارت دنبال ردیف نام می‌گردید، نه تمام کارت. `person.name` فقط نام ذخیره‌شده را می‌خواند. `console.log(person.name);` آن را در کنسول نشان می‌دهد. اگر به اشتباه Name را با حرف بزرگ بنویسید، شاید undefined بگیرید.","`person.name` liest nur den gespeicherten Namen. `console.log(person.name);` zeigt ihn in der Konsole.":"`person.name` فقط نام ذخیره‌شده را می‌خواند. `console.log(person.name);` آن را در کنسول نشان می‌دهد.","Eigenschaften ändern":"تغییر ویژگی‌ها","Eine Eigenschaft lässt sich mit person.ort = 'Köln' ändern. Das ist auch bei einem mit const angelegten Objekt erlaubt. Die gesamte Variable darf jedoch nicht neu zugewiesen werden. Eine Adresse auf einer Kontaktkarte darf sich nach einem Umzug ändern. `person.ort = 'Köln';` ersetzt nur den Wert der Eigenschaft ort. Die Variable person bleibt weiterhin dasselbe Objekt. Prüfe die Änderung mit einer anschließenden Konsolenausgabe.":"یک ویژگی را می‌شود با person.ort = 'Köln' تغییر داد. این کار در آبجکتی که با const ساخته شده هم مجاز است. اما تمام متغیر را نمی‌شود دوباره مقدار داد. آدرس روی یک کارت تماس بعد از کوچ کردن می‌تواند تغییر کند. `person.ort = 'Köln';` فقط مقدار ویژگی ort را عوض می‌کند. متغیر person همچنان همان آبجکت می‌ماند. تغییر را با یک خروجی کنسول بعدی بررسی کنید.","`person.ort = 'Köln';` ersetzt nur den Wert der Eigenschaft ort. Die Variable person bleibt weiterhin dasselbe Objekt.":"`person.ort = 'Köln';` فقط مقدار ویژگی ort را عوض می‌کند. متغیر person همچنان همان آبجکت می‌ماند.","Fehlende Werte erkennen":"شناختن مقدارهای ناموجود","Ein falsch geschriebener Eigenschaftsname liefert oft undefined. Prüfe die genaue Schreibweise. Gleiche Namen machen mehrere Objekte leichter vergleichbar. Fehlt ein Feld auf einer Karte, kannst du seinen Inhalt nicht lesen. `person.alter` liefert undefined, wenn alter nicht existiert. Prüfe die Schreibweise der Eigenschaft vor weiteren Berechnungen. Du kannst `person.alter = 30` ergänzen und danach erneut lesen.":"یک نام ویژگی که اشتباه نوشته شود اغلب undefined می‌دهد. املای دقیق را بررسی کنید. نام‌های یکسان مقایسهٔ چند آبجکت را آسان‌تر می‌کنند. اگر یک خانه روی کارت نباشد، نمی‌توانید محتوای آن را بخوانید. `person.alter` وقتی alter وجود نداشته باشد undefined می‌دهد. املای ویژگی را پیش از حساب‌های بعدی بررسی کنید. می‌توانید `person.alter = 30` را اضافه کنید و بعد دوباره بخوانید.","`person.alter` liefert undefined, wenn alter nicht existiert. Prüfe die Schreibweise der Eigenschaft vor weiteren Berechnungen.":"`person.alter` وقتی alter وجود نداشته باشد undefined می‌دهد. املای ویژگی را پیش از حساب‌های بعدی بررسی کنید.","Eigenschaftsname falsch geschrieben":"نام ویژگی اشتباه نوشته شد","Falsch: `console.log(person.Name);` liefert `undefined`, obwohl `name` gespeichert ist. Eigenschaftsnamen unterscheiden Groß- und Kleinschreibung. Richtig: `console.log(person.name);` zeigt `Amina`.":"اشتباه: `console.log(person.Name);` ‏`undefined` می‌دهد، با اینکه `name` ذخیره شده است. نام ویژگی‌ها بین حروف بزرگ و کوچک فرق می‌گذارند. درست: `console.log(person.name);` ‏`Amina` را نشان می‌دهد.","const-Objekt neu zugewiesen":"آبجکت const دوباره مقدار گرفت","Falsch: `const person = { name: 'Amina' }; person = { name: 'Mina' };` erzeugt `TypeError: Assignment to constant variable.`. Du darfst die const-Bindung nicht ersetzen. Richtig: `person.name = 'Mina';` ändert die Eigenschaft.":"اشتباه: `const person = { name: 'Amina' }; person = { name: 'Mina' };` خطای `TypeError: Assignment to constant variable.` می‌دهد. اجازه ندارید پیوند const را عوض کنید. درست: `person.name = 'Mina';` ویژگی را تغییر می‌دهد.","Was liefert person.name?":"person.name چه می‌دهد؟","Ort":"شهر","Name":"نام","Objektlänge":"طول آبجکت","Hier passt „Name“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „نام“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was bedeutet undefined?":"undefined یعنی چه؟","Wert fehlt möglicherweise":"شاید مقدار وجود ندارد","Alles ist gelöscht":"همه چیز پاک شده است","Wert ist null":"مقدار null است","Hier passt „Wert fehlt möglicherweise“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „شاید مقدار وجود ندارد“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was darfst du ändern?":"چه چیزی را اجازه دارید تغییر دهید؟","const person neu setzen":"دوباره مقدار دادن به const person","const entfernen":"برداشتن const","Hier passt „person.ort“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „person.ort“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Objekte ist die genaue JavaScript-Schreibweise wichtig.":"در آبجکت‌ها، املای دقیق JavaScript مهم است.","Nutze die Lösung `const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);` als Vergleich für deine eigene Übung.":"از راه‌حل `const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);` برای مقایسه با تمرین خودتان استفاده کنید.","HTML-Elemente finden und sicher verändern":"عنصرهای HTML را پیدا کنید و مطمئن تغییر دهید","DOM als Dokumentstruktur":"DOM به عنوان ساختار سند","Der Browser stellt HTML als Dokumentstruktur bereit. Diese Struktur heißt DOM. JavaScript kann darin gezielt Elemente suchen. Ein Stadtplan zeigt Straßen und Häuser; das DOM bildet die Struktur einer Webseite ab. `document.querySelector('#ausgabe')` sucht die passende ID. Das Zeichen # bedeutet, dass du ein bestimmtes Element meinst. Lege ein `<p id='ausgabe'>` an, damit die Suche erfolgreich ist.":"براوزر HTML را به شکل یک ساختار سند فراهم می‌کند. به این ساختار DOM می‌گویند. JavaScript می‌تواند در آن هدفمند دنبال عنصرها بگردد. یک نقشهٔ شهر سرک‌ها و خانه‌ها را نشان می‌دهد؛ DOM ساختار یک ویب‌سایت را نشان می‌دهد. `document.querySelector('#ausgabe')` دنبال ID مناسب می‌گردد. علامهٔ # یعنی شما یک عنصر معین را منظور دارید. یک `<p id='ausgabe'>` بسازید تا جستجو موفق باشد.","`document.querySelector('#ausgabe')` sucht die passende ID. Das Zeichen # bedeutet, dass du ein bestimmtes Element meinst.":"`document.querySelector('#ausgabe')` دنبال ID مناسب می‌گردد. علامهٔ # یعنی شما یک عنصر معین را منظور دارید.","Element per ID auswählen":"انتخاب عنصر با ID","querySelector findet ein Element anhand eines CSS-Selektors. Das Zeichen # steht für eine ID. Stimmen die Namen nicht überein, kommt null zurück. Eine Hausnummer muss genau stimmen, sonst findest du das Gebäude nicht. `const ausgabe = document.querySelector('#ausgabe');` speichert das gefundene Element. Ist die ID anders geschrieben, steht in ausgabe der Wert null. Prüfe den Namen im HTML und im JavaScript Zeichen für Zeichen.":"querySelector یک عنصر را بر اساس یک انتخابگر CSS پیدا می‌کند. علامهٔ # برای یک ID است. اگر نام‌ها جور نیایند، null برمی‌گردد. یک شمارهٔ خانه باید دقیقاً درست باشد، وگرنه ساختمان را پیدا نمی‌کنید. `const ausgabe = document.querySelector('#ausgabe');` عنصر پیدا شده را نگه می‌دارد. اگر ID طور دیگری نوشته شده باشد، در ausgabe مقدار null است. نام را در HTML و JavaScript حرف به حرف بررسی کنید.","`const ausgabe = document.querySelector('#ausgabe');` speichert das gefundene Element. Ist die ID anders geschrieben, steht in ausgabe der Wert null.":"`const ausgabe = document.querySelector('#ausgabe');` عنصر پیدا شده را نگه می‌دارد. اگر ID طور دیگری نوشته شده باشد، در ausgabe مقدار null است.","textContent einsetzen":"به کار بردن textContent","textContent ersetzt den sichtbaren Text. Anders als innerHTML behandelt es Nutzereingaben nicht als HTML-Markup. Das hilft gegen unerwünschte Codeausführung. Ein Hinweisschild kann einen neuen Text bekommen, ohne dass du das ganze Schild austauschst. `ausgabe.textContent = 'Willkommen';` ersetzt den sichtbaren Inhalt. Auch Zeichen wie `<` werden dabei als Text behandelt. Das ist wichtig, wenn später fremde Eingaben angezeigt werden.":"textContent متن قابل دید را عوض می‌کند. برخلاف innerHTML، ورودی‌های کاربر را به عنوان HTML تفسیر نمی‌کند. این در برابر اجرای ناخواستهٔ کد کمک می‌کند. یک تابلوی راهنما می‌تواند متن تازه بگیرد، بدون اینکه تمام تابلو را عوض کنید. `ausgabe.textContent = 'Willkommen';` محتوای قابل دید را عوض می‌کند. حتی نشانه‌هایی مثل `<` هم به عنوان متن در نظر گرفته می‌شوند. این مهم است، وقتی بعداً ورودی‌های دیگران نشان داده شوند.","`ausgabe.textContent = 'Willkommen';` ersetzt den sichtbaren Inhalt. Auch Zeichen wie `<` werden dabei als Text behandelt.":"`ausgabe.textContent = 'Willkommen';` محتوای قابل دید را عوض می‌کند. حتی نشانه‌هایی مثل `<` هم به عنوان متن در نظر گرفته می‌شوند.","Auf Existenz prüfen":"بررسی وجود داشتن","Prüfe das Element vor dem Zugriff. Eine einfache if-Abfrage verhindert Fehler bei null. Platziere das Skript so, dass das HTML bereits geladen wurde. Ein Briefkasten muss montiert sein, bevor du einen Brief einwerfen kannst.":"پیش از دسترسی، عنصر را بررسی کنید. یک if ساده از خطا در null جلوگیری می‌کند. اسکریپت را طوری بگذارید که HTML از قبل بارگیری شده باشد. یک صندوق پست باید نصب شده باشد، پیش از اینکه بتوانید نامه‌ای در آن بیندازید.","`if (ausgabe)` prüft, ob das Element gefunden wurde. Erst im erfolgreichen Zweig änderst du textContent.":"`if (ausgabe)` بررسی می‌کند که آیا عنصر پیدا شد. فقط در شاخهٔ موفق textContent را تغییر می‌دهید.","ID im HTML stimmt nicht":"ID در HTML درست نیست","Falsch: `document.querySelector('#anzeige').textContent = 'Hallo';` kann `TypeError: Cannot set properties of null` auslösen, wenn das HTML nur `id='ausgabe'` enthält. Richtig: `document.querySelector('#ausgabe').textContent = 'Hallo';` trifft das vorhandene Element.":"اشتباه: `document.querySelector('#anzeige').textContent = 'Hallo';` می‌تواند `TypeError: Cannot set properties of null` ایجاد کند، اگر HTML فقط `id='ausgabe'` داشته باشد. درست: `document.querySelector('#ausgabe').textContent = 'Hallo';` به عنصر موجود می‌رسد.","innerHTML für fremde Texte benutzt":"innerHTML برای متن‌های بیگانه به کار رفت","Falsch: `ausgabe.innerHTML = eingabe;` kann eingegebenes HTML als echte Elemente darstellen, statt es als Text zu zeigen. Richtig: `ausgabe.textContent = eingabe;` zeigt auch `<b>Hallo</b>` wörtlich an.":"اشتباه: `ausgabe.innerHTML = eingabe;` ممکن است HTML واردشده را به عنوان عنصرهای واقعی نشان دهد، به جای اینکه آن را به شکل متن نشان دهد. درست: `ausgabe.textContent = eingabe;` حتی `<b>Hallo</b>` را کلمه به کلمه نشان می‌دهد.","Was findet #ausgabe?":"‎#ausgabe چه چیزی را پیدا می‌کند؟","Alle Links":"همهٔ لینک‌ها","Element mit passender ID":"عنصری با ID مناسب","Ein Stylesheet":"یک شیوه‌نامه (Stylesheet)","Hier passt „Element mit passender ID“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „عنصری با ID مناسب“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was setzt sicheren Text?":"چه چیزی متن مطمئن می‌گذارد؟","Hier passt „textContent“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „textContent“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was bedeutet null?":"null یعنی چه؟","Leerer Text":"متن خالی","Keine CSS-Regel":"هیچ قاعدهٔ CSS","Kein Element gefunden":"هیچ عنصری پیدا نشد","Hier passt „Kein Element gefunden“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „هیچ عنصری پیدا نشد“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei DOM ist die genaue JavaScript-Schreibweise wichtig.":"در DOM، املای دقیق JavaScript مهم است.","Nutze die Lösung `const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';` als Vergleich für deine eigene Übung.":"از راه‌حل `const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';` برای مقایسه با تمرین خودتان استفاده کنید.","Events":"رویدادها (Events)","Klicks mit addEventListener verarbeiten":"کلیک‌ها را با addEventListener پردازش کنید","Klick als Ereignis":"کلیک به عنوان رویداد","Ein Event ist ein Ereignis wie ein Klick. JavaScript kann darauf warten. So wird eine Seite interaktiv. Eine Türklingel löst erst beim Drücken ein Signal aus; ein Klick ist ähnlich. `addEventListener('click', ...)` wartet auf das Ereignis. Die Funktion wird nicht bereits beim Laden der Seite ausgeführt. So bleibt der Knopf für weitere Klicks bereit.":"یک Event رویدادی مثل یک کلیک است. JavaScript می‌تواند منتظر آن بماند. به این ترتیب یک صفحه تعاملی می‌شود. زنگ دروازه فقط با فشار دادن یک علامت می‌دهد؛ یک کلیک هم شبیه آن است. `addEventListener('click', ...)` منتظر رویداد می‌ماند. تابع همان هنگام بارگیری صفحه اجرا نمی‌شود. به این ترتیب دکمه برای کلیک‌های بعدی آماده می‌ماند.","`addEventListener('click', ...)` wartet auf das Ereignis. Die Funktion wird nicht bereits beim Laden der Seite ausgeführt.":"`addEventListener('click', ...)` منتظر رویداد می‌ماند. تابع همان هنگام بارگیری صفحه اجرا نمی‌شود.","Listener registrieren":"ثبت کردن Listener","addEventListener verbindet ein Element mit einer Funktion. Die Funktion wird erst beim Ereignis ausgeführt. Achte auf die Schreibweise click. Ein Empfangsdienst erhält eine Telefonnummer, nicht einen schon beendeten Anruf. `knopf.addEventListener('click', melden)` übergibt die Funktion selbst. Mit `melden()` würdest du sie bereits beim Registrieren aufrufen. Achte deshalb darauf, ob hinter dem Funktionsnamen Klammern stehen.":"addEventListener یک عنصر را با یک تابع وصل می‌کند. تابع فقط هنگام رویداد اجرا می‌شود. به املای click دقت کنید. یک دفتر پذیرش یک شمارهٔ تیلفون می‌گیرد، نه یک تماس که از قبل تمام شده است. `knopf.addEventListener('click', melden)` خود تابع را می‌دهد. با `melden()` آن را همان هنگام ثبت کردن صدا می‌زدید. به همین دلیل دقت کنید که آیا بعد از نام تابع قوس هست یا نه.","`knopf.addEventListener('click', melden)` übergibt die Funktion selbst. Mit `melden()` würdest du sie bereits beim Registrieren aufrufen.":"`knopf.addEventListener('click', melden)` خود تابع را می‌دهد. با `melden()` آن را همان هنگام ثبت کردن صدا می‌زدید.","Rückmeldung zeigen":"نشان دادن پاسخ","Im Listener kannst du Text ändern. Eine Meldung wie Gespeichert bestätigt die Aktion. Das ist für Nutzerinnen und Nutzer eine wichtige Rückmeldung. Eine Quittung bestätigt eine Zahlung; ein Statussatz bestätigt einen Klick. `ausgabe.textContent = 'Gespeichert';` aktualisiert die Meldung. Die Änderung erfolgt innerhalb der Klick-Funktion. Klicke zweimal und kontrolliere, dass die Meldung verständlich bleibt.":"در Listener می‌توانید متن را تغییر دهید. پیامی مثل Gespeichert کار را تأیید می‌کند. این یک پاسخ مهم برای کاربران است. یک رسید یک پرداخت را تأیید می‌کند؛ یک جملهٔ وضعیت یک کلیک را تأیید می‌کند. `ausgabe.textContent = 'Gespeichert';` پیام را به‌روز می‌کند. این تغییر داخل تابع کلیک انجام می‌شود. دو بار کلیک کنید و بررسی کنید که پیام قابل فهم بماند.","`ausgabe.textContent = 'Gespeichert';` aktualisiert die Meldung. Die Änderung erfolgt innerhalb der Klick-Funktion.":"`ausgabe.textContent = 'Gespeichert';` پیام را به‌روز می‌کند. این تغییر داخل تابع کلیک انجام می‌شود.","Tastatur prüfen":"بررسی کیبورد","Ein echtes button-Element funktioniert auch mit der Tastatur. Teste Tab und Enter. Ein klickbarer Absatz ist dafür keine gleichwertige Lösung. Eine barrierefreie Tür lässt sich auf mehreren Wegen öffnen.":"یک عنصر button واقعی با کیبورد هم کار می‌کند. Tab و Enter را آزمایش کنید. یک پاراگراف قابل کلیک برای این کار راه‌حل برابر نیست. یک دروازهٔ دسترس‌پذیر از چند راه باز می‌شود.","Ein HTML-button reagiert neben der Maus auch auf Tastatureingaben. Erreiche den Knopf mit Tab und aktiviere ihn mit Enter.":"یک button در HTML علاوه بر موس به ورودی‌های کیبورد هم واکنش نشان می‌دهد. با Tab به دکمه برسید و با Enter آن را فعال کنید.","Funktion sofort statt beim Klick ausgeführt":"تابع فوراً به جای هنگام کلیک اجرا شد","Falsch: `knopf.addEventListener('click', melden());` ruft melden sofort auf; beim Klick passiert danach nichts oder ein TypeError entsteht. Richtig: `knopf.addEventListener('click', melden);` übergibt die Funktion ohne Klammern.":"اشتباه: `knopf.addEventListener('click', melden());` ‏melden را فوراً صدا می‌زند؛ هنگام کلیک بعد از آن یا هیچ اتفاقی نمی‌افتد یا یک TypeError پیدا می‌شود. درست: `knopf.addEventListener('click', melden);` تابع را بدون قوس می‌دهد.","Listener an null registriert":"Listener روی null ثبت شد","Falsch: `document.querySelector('#knop').addEventListener('click', melden);` löst `TypeError: Cannot read properties of null` aus, wenn der Knopf `id='knopf'` heißt. Richtig: `document.querySelector('#knopf').addEventListener('click', melden);`.":"اشتباه: `document.querySelector('#knop').addEventListener('click', melden);` خطای `TypeError: Cannot read properties of null` می‌دهد، اگر نام دکمه `id='knopf'` باشد. درست: `document.querySelector('#knopf').addEventListener('click', melden);`.","Wie heißt das Klick-Ereignis?":"رویداد کلیک چه نام دارد؟","Hier passt „click“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „click“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was registriert einen Listener?":"چه چیزی یک Listener را ثبت می‌کند؟","Hier passt „addEventListener“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „addEventListener“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Warum button verwenden?":"چرا button را به کار ببریم؟","Es lädt schneller":"سریع‌تر بارگیری می‌شود","Es braucht kein CSS":"به CSS نیاز ندارد","Es ist per Tastatur bedienbar":"با کیبورد قابل استفاده است","Hier passt „Es ist per Tastatur bedienbar“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „با کیبورد قابل استفاده است“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Events ist die genaue JavaScript-Schreibweise wichtig.":"در رویدادها، املای دقیق JavaScript مهم است.","Nutze die Lösung `const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });` als Vergleich für deine eigene Übung.":"از راه‌حل `const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });` برای مقایسه با تمرین خودتان استفاده کنید.","Konsole":"کنسول","JavaScript-Fehler systematisch untersuchen":"خطاهای JavaScript را منظم بررسی کنید","Werte protokollieren":"ثبت کردن مقدارها","console.log zeigt Werte in der Entwicklerkonsole. Damit erkennst du Zwischenergebnisse. Beschrifte deine Ausgaben verständlich. Ein Techniker liest die Anzeige eines Geräts, bevor er etwas austauscht. `console.log('Gefunden:', Boolean(element));` zeigt einen beschrifteten Wert. Boolean wandelt die Existenz des Elements in true oder false um. So erkennst du, ob die Suche überhaupt erfolgreich war.":"console.log مقدارها را در کنسول توسعه‌دهنده نشان می‌دهد. با آن نتیجه‌های میانی را می‌شناسید. خروجی‌های خود را قابل فهم برچسب بزنید. یک تکنیشن پیش از عوض کردن چیزی نمایش یک دستگاه را می‌خواند. `console.log('Gefunden:', Boolean(element));` یک مقدار برچسب‌دار نشان می‌دهد. Boolean وجود داشتن عنصر را به true یا false تبدیل می‌کند. به این ترتیب می‌فهمید که آیا جستجو اصلاً موفق بود.","`console.log('Gefunden:', Boolean(element));` zeigt einen beschrifteten Wert. Boolean wandelt die Existenz des Elements in true oder false um.":"`console.log('Gefunden:', Boolean(element));` یک مقدار برچسب‌دار نشان می‌دهد. Boolean وجود داشتن عنصر را به true یا false تبدیل می‌کند.","SyntaxError erkennen":"شناختن SyntaxError","Ein SyntaxError weist auf ungültige Schreibweise hin. Prüfe Klammern und Anführungszeichen. Die Zeilennummer hilft beim Suchen. Ein falsch geschriebenes Wort auf einem Formular verhindert das Verständnis. `console.log('Hallo'` fehlt die schließende runde Klammer. Der Browser meldet einen SyntaxError und führt den Code nicht aus. Ergänze `);` und starte die Prüfung erneut.":"یک SyntaxError به املای نامعتبر اشاره می‌کند. قوس‌ها و علامه‌های نقل‌قول را بررسی کنید. شمارهٔ خط در جستجو کمک می‌کند. یک کلمهٔ اشتباه نوشته‌شده در یک فورم مانع فهمیدن می‌شود. در `console.log('Hallo'` قوس گرد بسته کم است. براوزر یک SyntaxError می‌دهد و کد را اجرا نمی‌کند. `);` را اضافه کنید و بررسی را دوباره شروع کنید.","`console.log('Hallo'` fehlt die schließende runde Klammer. Der Browser meldet einen SyntaxError und führt den Code nicht aus.":"در `console.log('Hallo'` قوس گرد بسته کم است. براوزر یک SyntaxError می‌دهد و کد را اجرا نمی‌کند.","TypeError verstehen":"فهمیدن TypeError","Ein TypeError kann bei einem Zugriff auf null entstehen. Kontrolliere das Ergebnis von querySelector. Eine if-Abfrage schützt vor dem Zugriff. Eine Lieferung an eine unbekannte Adresse kann nicht ankommen. `document.querySelector('#fehlt')` liefert null, wenn es kein Ziel gibt. Ein direkter Zugriff auf `.textContent` erzeugt dann einen TypeError. Mit `if (element)` vermeidest du diesen Zugriff.":"یک TypeError ممکن است هنگام دسترسی به null پیدا شود. نتیجهٔ querySelector را بررسی کنید. یک if از دسترسی محافظت می‌کند. یک تحویل به یک آدرس ناشناخته نمی‌تواند برسد. `document.querySelector('#fehlt')` وقتی هدفی نباشد null می‌دهد. در آن صورت دسترسی مستقیم به `.textContent` یک TypeError ایجاد می‌کند. با `if (element)` از این دسترسی جلوگیری می‌کنید.","`document.querySelector('#fehlt')` liefert null, wenn es kein Ziel gibt. Ein direkter Zugriff auf `.textContent` erzeugt dann einen TypeError.":"`document.querySelector('#fehlt')` وقتی هدفی نباشد null می‌دهد. در آن صورت دسترسی مستقیم به `.textContent` یک TypeError ایجاد می‌کند.","Gezielt erneut testen":"آزمایش دوبارهٔ هدفمند","Ändere jeweils nur eine Stelle. Starte danach den Test erneut. Entferne überflüssige Debug-Ausgaben vor der Veröffentlichung. Beim Reparieren eines Fahrrads prüfst du nach jeder Änderung nur das betroffene Teil. Setze eine beschriftete console.log-Ausgabe vor den verdächtigen Abschnitt. Beobachte den Wert und ändere danach genau eine Anweisung. Wiederhole den Test, bis die Fehlermeldung verschwindet.":"هر بار فقط یک جا را تغییر دهید. بعد از آن آزمایش را دوباره شروع کنید. خروجی‌های اضافی Debug را پیش از نشر پاک کنید. هنگام ترمیم یک بایسکل بعد از هر تغییر فقط همان بخش مربوط را بررسی می‌کنید. یک خروجی console.log برچسب‌دار را پیش از بخش مشکوک بگذارید. مقدار را ببینید و بعد دقیقاً یک دستور را تغییر دهید. آزمایش را تکرار کنید تا پیام خطا ناپدید شود.","Setze eine beschriftete console.log-Ausgabe vor den verdächtigen Abschnitt. Beobachte den Wert und ändere danach genau eine Anweisung.":"یک خروجی console.log برچسب‌دار را پیش از بخش مشکوک بگذارید. مقدار را ببینید و بعد دقیقاً یک دستور را تغییر دهید.","Syntaxfehler überlesen":"نادیده گرفتن خطای نحوی","Falsch: `console.log('Hallo'` erzeugt `SyntaxError: missing ) after argument list` oder eine entsprechende Syntaxmeldung. Die schließende Klammer fehlt. Richtig: `console.log('Hallo');` lässt sich ausführen.":"اشتباه: `console.log('Hallo'` خطای `SyntaxError: missing ) after argument list` یا یک پیام نحوی مشابه ایجاد می‌کند. قوس بسته کم است. درست: `console.log('Hallo');` اجرا می‌شود.","Auf null ohne Prüfung zugegriffen":"دسترسی به null بدون بررسی","Falsch: `document.querySelector('#fehlt').textContent = 'OK';` löst `TypeError: Cannot set properties of null` aus, wenn es das Element nicht gibt. Richtig: `const el = document.querySelector('#fehlt'); if (el) el.textContent = 'OK';`.":"اشتباه: `document.querySelector('#fehlt').textContent = 'OK';` خطای `TypeError: Cannot set properties of null` می‌دهد، اگر آن عنصر وجود نداشته باشد. درست: `const el = document.querySelector('#fehlt'); if (el) el.textContent = 'OK';`.","Was zeigt console.log?":"console.log چه نشان می‌دهد؟","Nur Bilder":"فقط عکس‌ها","Werte in der Konsole":"مقدارها در کنسول","Nur HTML":"فقط HTML","Hier passt „Werte in der Konsole“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „مقدارها در کنسول“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was ist SyntaxError?":"SyntaxError چیست؟","Ungültige Schreibweise":"املای نامعتبر","Fehlendes Internet":"انترنت قطع","Falsche Farbe":"رنگ اشتباه","Hier passt „Ungültige Schreibweise“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „املای نامعتبر“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Was vor textContent prüfen?":"پیش از textContent چه چیزی را بررسی کنیم؟","Schriftgröße":"اندازهٔ فونت","Fensterhöhe":"ارتفاع پنجره","Element ist nicht null":"عنصر null نیست","Hier passt „Element ist nicht null“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „عنصر null نیست“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Bei Konsole ist die genaue JavaScript-Schreibweise wichtig.":"در کنسول، املای دقیق JavaScript مهم است.","Nutze die Lösung `const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));` als Vergleich für deine eigene Übung.":"از راه‌حل `const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));` برای مقایسه با تمرین خودتان استفاده کنید.","Projekt: To-do-Liste":"پروژه: لست کارها","Eine kleine Aufgabenliste mit Eingabe und Knopf bauen":"یک لست کوچک کارها با ورودی و دکمه بسازید","Eingabe beschriften":"برچسب زدن به ورودی","Eine Aufgabenliste braucht ein Eingabefeld. Verbinde label und input über for und id. Der Knopf startet das Hinzufügen. Ein Notizblock braucht eine Zeile für jede neue Aufgabe.":"یک لست کارها به یک خانهٔ ورودی نیاز دارد. label و input را از راه for و id وصل کنید. دکمه اضافه کردن را شروع می‌کند. یک کتابچهٔ یادداشت برای هر کار تازه یک خط لازم دارد.","`<label for='aufgabe'>` beschreibt das Eingabefeld. Das zugehörige input hat die ID aufgabe.":"`<label for='aufgabe'>` خانهٔ ورودی را توصیف می‌کند. input مربوط ID ‏aufgabe را دارد.","Leere Aufgaben vermeiden":"جلوگیری از کارهای خالی","Mit value liest du die Eingabe. trim entfernt Leerzeichen am Anfang und Ende. Eine leere Eingabe darf keinen Eintrag erzeugen. Auf einem Einkaufszettel hilft eine leere Zeile niemandem. `feld.value.trim()` entfernt Leerzeichen am Rand. `if (!text) return;` beendet den Klickablauf bei leerem Text. Teste Eingaben mit nur drei Leerzeichen und mit einem echten Wort.":"با value ورودی را می‌خوانید. trim فاصله‌های شروع و پایان را پاک می‌کند. یک ورودی خالی نباید عنصری بسازد. در یک لست خرید یک خط خالی به کسی کمک نمی‌کند. `feld.value.trim()` فاصله‌های دو طرف را پاک می‌کند. `if (!text) return;` روند کلیک را در متن خالی تمام می‌کند. ورودی‌ها را با فقط سه فاصله و با یک کلمهٔ واقعی آزمایش کنید.","`feld.value.trim()` entfernt Leerzeichen am Rand. `if (!text) return;` beendet den Klickablauf bei leerem Text.":"`feld.value.trim()` فاصله‌های دو طرف را پاک می‌کند. `if (!text) return;` روند کلیک را در متن خالی تمام می‌کند.","Listeneinträge erzeugen":"ساختن عنصرهای لست","createElement erzeugt ein neues li-Element. Mit textContent setzt du den Aufgabentext sicher. appendChild fügt den Eintrag in die Liste ein. Eine neue Karteikarte wird erst erstellt und danach beschriftet. `document.createElement('li')` erzeugt einen Listeneintrag. `li.textContent = text` schreibt die Aufgabe sicher hinein. `liste.appendChild(li)` hängt den Eintrag an die sichtbare Liste.":"createElement یک عنصر li تازه می‌سازد. با textContent متن کار را مطمئن می‌گذارید. appendChild عنصر را به لست اضافه می‌کند. یک کارت یادداشت تازه اول ساخته و بعد نوشته می‌شود. `document.createElement('li')` یک عنصر لست می‌سازد. `li.textContent = text` کار را مطمئن داخل آن می‌نویسد. `liste.appendChild(li)` عنصر را به لست قابل دید اضافه می‌کند.","`document.createElement('li')` erzeugt einen Listeneintrag. `li.textContent = text` schreibt die Aufgabe sicher hinein.":"`document.createElement('li')` یک عنصر لست می‌سازد. `li.textContent = text` کار را مطمئن داخل آن می‌نویسد.","Aufgaben nach Klick anzeigen":"نشان دادن کارها بعد از کلیک","Leere das Feld nach dem Hinzufügen. Probiere mehrere Aufgaben nacheinander. Kontrolliere die Bedienung auch auf einem kleinen Handy. Nach dem Eintragen einer Aufgabe ist der Stift wieder frei für die nächste. `feld.value = ''` leert das Eingabefeld nach dem Hinzufügen. Ein erneuter Klick mit leerem Feld darf keinen Eintrag erzeugen. Teste zwei unterschiedliche Aufgaben nacheinander.":"بعد از اضافه کردن خانه را خالی کنید. چند کار را پشت سر هم امتحان کنید. کار کردن را در یک موبایل کوچک هم بررسی کنید. بعد از نوشتن یک کار، قلم دوباره برای کار بعدی آزاد است. `feld.value = ''` خانهٔ ورودی را بعد از اضافه کردن خالی می‌کند. یک کلیک دوباره با خانهٔ خالی نباید عنصری بسازد. دو کار مختلف را پشت سر هم آزمایش کنید.","`feld.value = ''` leert das Eingabefeld nach dem Hinzufügen. Ein erneuter Klick mit leerem Feld darf keinen Eintrag erzeugen.":"`feld.value = ''` خانهٔ ورودی را بعد از اضافه کردن خالی می‌کند. یک کلیک دوباره با خانهٔ خالی نباید عنصری بسازد.","Leere Aufgaben gespeichert":"کارهای خالی ذخیره شدند","Falsch: `aufgaben.push(feld.value);` übernimmt auch `   ` als Aufgabe; in der Vorschau erscheint ein leerer Listeneintrag. Richtig: `const text = feld.value.trim(); if (!text) return; aufgaben.push(text);`.":"اشتباه: `aufgaben.push(feld.value);` حتی `   ` را هم به عنوان کار می‌پذیرد؛ در پیش‌نمایش یک عنصر خالی لست دیده می‌شود. درست: `const text = feld.value.trim(); if (!text) return; aufgaben.push(text);`.","Eingabetext mit innerHTML eingesetzt":"متن ورودی با innerHTML گذاشته شد","Falsch: `liste.innerHTML += '<li>' + feld.value + '</li>';` interpretiert eingegebenes HTML und kann unerwünschte Elemente erzeugen. Richtig: `const li = document.createElement('li'); li.textContent = feld.value; liste.appendChild(li);`.":"اشتباه: `liste.innerHTML += '<li>' + feld.value + '</li>';` ‏HTML واردشده را تفسیر می‌کند و ممکن است عنصرهای ناخواسته بسازد. درست: `const li = document.createElement('li'); li.textContent = feld.value; liste.appendChild(li);`.","Was entfernt trim?":"trim چه چیزی را پاک می‌کند؟","Rand-Leerzeichen":"فاصله‌های دو طرف","Alle Zahlen":"همهٔ عددها","Alle Einträge":"همهٔ عنصرها","Hier passt „Rand-Leerzeichen“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „فاصله‌های دو طرف“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Wie erzeugst du li?":"li را چطور می‌سازید؟","Hier passt „createElement“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.":"اینجا „createElement“ درست است، چون کاری را که در مثال تمرین شد درست توصیف می‌کند.","Wie zeigst du Text sicher?":"متن را چطور مطمئن نشان می‌دهید؟","Bei Projekt: To-do-Liste ist die genaue JavaScript-Schreibweise wichtig.":"در پروژهٔ لست کارها، املای دقیق JavaScript مهم است.","Nutze die Lösung `const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });` als Vergleich für deine eigene Übung.":"از راه‌حل `const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });` برای مقایسه با تمرین خودتان استفاده کنید.","Eine Zahl wie 12 lässt sich direkt berechnen. Ohne Anführungszeichen speichert JavaScript einen numerischen Wert. Für einen festen Preis ist const geeignet. Ein Preisetikett trägt eine Zahl, nicht den geschriebenen Namen der Zahl. Zeile 1 legt preis mit `const` fest; Zeile 2 legt ort als Zeichenkette an. Vergleiche `12 + 3` mit `'12' + 3` und beobachte `15` gegenüber `123`.":"عددی مثل 12 را می‌شود مستقیم حساب کرد. بدون علامهٔ نقل‌قول، JavaScript یک مقدار عددی نگه می‌دارد. برای یک قیمت ثابت const مناسب است. یک برچسب قیمت یک عدد دارد، نه نام نوشته‌شدهٔ آن عدد را. خط 1 ‏preis را با `const` تعیین می‌کند؛ خط 2 ‏ort را به شکل رشتهٔ متنی می‌سازد. `12 + 3` را با `'12' + 3` مقایسه کنید و `15` را در برابر `123` ببینید.","Ein Boolean ist entweder true oder false. Er steht ohne Anführungszeichen im Code. So kannst du Zustände wie offen oder geschlossen speichern. Ein Lichtschalter hat zwei Zustände; Boolean bildet genau diese Unterscheidung ab. `const offen = true;` legt einen echten Wahrheitswert an. `if (offen)` kann damit eine Entscheidung treffen, ohne Text zu vergleichen.":"یک Boolean یا true است یا false. بدون علامهٔ نقل‌قول در کد نوشته می‌شود. به این ترتیب می‌توانید وضعیت‌هایی مثل باز یا بسته را نگه دارید. یک سویچ چراغ دو وضعیت دارد؛ Boolean دقیقاً همین تفاوت را نشان می‌دهد. `const offen = true;` یک مقدار درست/نادرست واقعی می‌سازد. `if (offen)` با آن می‌تواند تصمیم بگیرد، بدون اینکه متن را مقایسه کند.","Ein Array sammelt mehrere Werte in eckigen Klammern. Trenne die Einträge mit Kommas. So bleibt eine Einkaufsliste in einer einzigen Variablen. Eine Einkaufstasche enthält mehrere Produkte; ein Array hält ihre Namen zusammen. `const einkauf = ['Brot', 'Milch'];` erzeugt zwei Einträge. Die eckigen Klammern gehören zur Liste, die Anführungszeichen zu jedem Text.":"یک آرایه چند مقدار را داخل قوس‌های چهارگوش جمع می‌کند. عنصرها را با کامه جدا کنید. به این ترتیب یک لست خرید در یک متغیر واحد می‌ماند. یک خریطهٔ خرید چند جنس دارد؛ یک آرایه نام‌های آن‌ها را یک‌جا نگه می‌دارد. `const einkauf = ['Brot', 'Milch'];` دو عنصر می‌سازد. قوس‌های چهارگوش به لست تعلق دارند و علامهٔ نقل‌قول به هر متن.","Eine Schleife führt denselben Ablauf mehrmals aus. Du musst die Anweisung nicht kopieren. Das ist bei einer Liste von Namen besonders praktisch. Eine Lehrkraft ruft alle Namen der Anwesenheitsliste nacheinander auf. `for (const name of namen)` besucht jeden vorhandenen Eintrag. Der Block in geschweiften Klammern wird für jeden Namen wiederholt.":"یک حلقه یک روند را چند بار اجرا می‌کند. لازم نیست دستور را کاپی کنید. این برای یک لست نام‌ها به‌خصوص کاربردی است. یک معلم همهٔ نام‌های لست حاضری را یکی پس از دیگری صدا می‌زند. `for (const name of namen)` به هر عنصر موجود سر می‌زند. بلاک داخل قوس‌های گُل‌دار برای هر نام تکرار می‌شود.","Eine klassische for-Schleife benutzt oft let i = 0. Nach jedem Durchlauf erhöht i++ den Zähler. Mit i < 3 läuft der Block genau dreimal. Eine Nummernausgabe am Schalter zählt 0, 1, 2 und stoppt dann. `let i = 0` setzt den Anfangswert, `i < 3` prüft die Grenze. `i++` erhöht die Nummer nach jedem Durchlauf um eins.":"یک حلقهٔ for کلاسیک اغلب let i = 0 را به کار می‌برد. بعد از هر دور i++ شمارنده را زیاد می‌کند. با i < 3 بلاک دقیقاً سه بار اجرا می‌شود. یک دستگاه نوبت در کاونتر 0، 1، 2 می‌شمارد و بعد می‌ایستد. `let i = 0` مقدار شروع را می‌گذارد و `i < 3` حد را بررسی می‌کند. `i++` بعد از هر دور شماره را یکی زیاد می‌کند.","Eine Schleife braucht eine erreichbare Abbruchbedingung. Ohne Änderung des Zählers kann sie endlos laufen. Prüfe den Ablauf zunächst mit wenigen Werten. Eine Rolltreppe ohne Ausgang wäre gefährlich; eine Schleife ohne Ende blockiert den Ablauf. Bei `for (let i = 0; i < 3; i++)` ist das Ende erreichbar. Wenn `i++` fehlt, bleibt die Bedingung dauerhaft wahr.":"یک حلقه به یک شرط توقف قابل رسیدن نیاز دارد. بدون تغییر شمارنده ممکن است بی‌پایان اجرا شود. روند را اول با چند مقدار کم بررسی کنید. یک زینهٔ برقی بدون خروجی خطرناک می‌بود؛ یک حلقهٔ بی‌پایان روند را متوقف می‌کند. در `for (let i = 0; i < 3; i++)` پایان قابل رسیدن است. اگر `i++` نباشد، شرط همیشه درست می‌ماند.","Eine Funktion bündelt einen wiederkehrenden Ablauf. function leitet die Definition ein. Der Name beschreibt die Aufgabe möglichst genau. Eine Kaffeemaschine erledigt nach dem Start immer dieselben Schritte. `function doppelt(zahl)` gibt dem Ablauf einen Namen und einen Parameter. Die geschweiften Klammern umschließen die Rechenanweisung.":"یک تابع یک روند تکراری را یک‌جا جمع می‌کند. function تعریف را شروع می‌کند. نام باید کار را تا حد ممکن دقیق توصیف کند. یک ماشین قهوه بعد از روشن شدن همیشه همان قدم‌ها را انجام می‌دهد. `function doppelt(zahl)` به روند یک نام و یک پارامتر می‌دهد. قوس‌های گُل‌دار دستور حساب را در بر می‌گیرند.","In runden Klammern stehen Parameter. Beim Aufruf wird für jeden Parameter ein Wert übergeben. Im Funktionskörper kannst du damit rechnen. Eine Bestellung nennt die gewünschte Menge; ein Parameter übernimmt diesen Wert. `doppelt(4)` übergibt die Zahl vier an den Parameter zahl. Im Funktionskörper steht dann für zahl genau dieser Wert.":"داخل قوس‌های گرد پارامترها هستند. هنگام صدا زدن برای هر پارامتر یک مقدار داده می‌شود. در بدنهٔ تابع می‌توانید با آن حساب کنید. یک سفارش مقدار دلخواه را نام می‌برد؛ یک پارامتر این مقدار را می‌گیرد. `doppelt(4)` عدد چهار را به پارامتر zahl می‌دهد. در بدنهٔ تابع به جای zahl دقیقاً همین مقدار قرار می‌گیرد.","Ein Objekt speichert zusammengehörige Angaben. Zwischen geschweiften Klammern stehen Eigenschaft und Wert. Ein Doppelpunkt trennt beide Teile. Eine Kontaktkarte hält Name und Ort einer Person beisammen. `const person = { name: 'Amina', ort: 'Bonn' };` erstellt zwei Eigenschaften. Der Doppelpunkt verbindet jeweils Schlüssel und Wert.":"یک آبجکت معلومات مربوط به هم را نگه می‌دارد. بین قوس‌های گُل‌دار ویژگی و مقدار می‌آیند. یک دونقطه هر دو بخش را جدا می‌کند. یک کارت تماس نام و شهر یک شخص را کنار هم نگه می‌دارد. `const person = { name: 'Amina', ort: 'Bonn' };` دو ویژگی می‌سازد. دونقطه هر بار کلید و مقدار را به هم وصل می‌کند.","Prüfe das Element vor dem Zugriff. Eine einfache if-Abfrage verhindert Fehler bei null. Platziere das Skript so, dass das HTML bereits geladen wurde. Ein Briefkasten muss montiert sein, bevor du einen Brief einwerfen kannst. `if (ausgabe)` prüft, ob das Element gefunden wurde. Erst im erfolgreichen Zweig änderst du textContent.":"پیش از دسترسی، عنصر را بررسی کنید. یک if ساده از خطا در null جلوگیری می‌کند. اسکریپت را طوری بگذارید که HTML از قبل بارگیری شده باشد. یک صندوق پست باید نصب شده باشد، پیش از اینکه بتوانید نامه‌ای در آن بیندازید. `if (ausgabe)` بررسی می‌کند که آیا عنصر پیدا شد. فقط در شاخهٔ موفق textContent را تغییر می‌دهید.","Ein echtes button-Element funktioniert auch mit der Tastatur. Teste Tab und Enter. Ein klickbarer Absatz ist dafür keine gleichwertige Lösung. Eine barrierefreie Tür lässt sich auf mehreren Wegen öffnen. Ein HTML-button reagiert neben der Maus auch auf Tastatureingaben. Erreiche den Knopf mit Tab und aktiviere ihn mit Enter.":"یک عنصر button واقعی با کیبورد هم کار می‌کند. Tab و Enter را آزمایش کنید. یک پاراگراف قابل کلیک برای این کار راه‌حل برابر نیست. یک دروازهٔ دسترس‌پذیر از چند راه باز می‌شود. یک button در HTML علاوه بر موس به ورودی‌های کیبورد هم واکنش نشان می‌دهد. با Tab به دکمه برسید و با Enter آن را فعال کنید.","Eine Aufgabenliste braucht ein Eingabefeld. Verbinde label und input über for und id. Der Knopf startet das Hinzufügen. Ein Notizblock braucht eine Zeile für jede neue Aufgabe. `<label for='aufgabe'>` beschreibt das Eingabefeld. Das zugehörige input hat die ID aufgabe.":"یک لست کارها به یک خانهٔ ورودی نیاز دارد. label و input را از راه for و id وصل کنید. دکمه اضافه کردن را شروع می‌کند. یک کتابچهٔ یادداشت برای هر کار تازه یک خط لازم دارد. `<label for='aufgabe'>` خانهٔ ورودی را توصیف می‌کند. input مربوط ID ‏aufgabe را دارد."};})(typeof window!=="undefined"?window:globalThis);
